{"message":"前回エラーはstrokeの制御点数にあります。stroke APIは厳密に「4個の制御点」が必要です。3個や5個ではエラーになります。またradiusも4個にしてください。他要件は維持した上で、すべてのstrokeの制御点・半径配列を4個に修正します。造形密度や根元～先端の太さ変化は維持しつつ、union内の本数・分布・命名などは前提どおりです。","changes":[{"path":"program.upsert","value":{"id":"model-1","name":"炎と蔓の盛り装飾フレーム","x":0,"y":0,"color":"#888888","size":[65,95,12],"source":"const W=65,D=95,H=12;
const baseT=3;
const decoZ0=3.5,decoZ1=11.5;
const Rmain=4.2,Rtip=1.2;
const outR=7,inR=5;
const openW=W-18,openD=D-22;
const outer=roundedBox([W,D,baseT],outR);
const inner=move(roundedBox([openW,openD,baseT+0.6],inR),[(W-openW)/2,(D-openD)/2,-0.3]);
const base=subtract(outer,inner);
// ========== 四隅 盛り装飾 ==========
// 上左
const topLeft = union(
 stroke([[8,8,decoZ0],[2,20,(decoZ1+decoZ0)/1.7],[15,34,decoZ1-1],[29,23,decoZ0+2]], [Rmain,3,2.2,Rtip],0.9),
 stroke([[11,7,decoZ0+1],[7,23,8],[15,32,decoZ1],[24,19,decoZ0+2.5] , [Rmain*0.82,2.6,1.4,Rtip*0.9],0.7),
 stroke([[13,8,decoZ0+0.5],[9,15,9.8],[7,28,11],[18,27,decoZ1]], [2.4,2,1.3,1.1],0.58),
 stroke([[8,13,decoZ0+0.9],[3,23,8],[8,34,10.2],[19,24,decoZ0+3.5]], [2,2,1.2,1],0.56)
);
// 上右（右上）
const topRight = union(
 stroke([[W-8,8,decoZ0],[W-2,22,9],[W-13,34,decoZ1-1.1],[W-29,21,decoZ0+2]], [Rmain,3,2.2,Rtip],0.9),
 stroke([[W-11,7,decoZ0],[W-7,24,8],[W-18,30,decoZ1-0.3],[W-27,17,decoZ0+2.3]], [Rmain*0.82,2.1,1.4,Rtip*0.9],0.68),
 stroke([[W-18,11,decoZ0+1.5],[W-12,24,10],[W-19,27,decoZ1-0.8],[W-28,13,decoZ0+2.7]], [Rmain*0.9,1.9,1.2,0.9],0.68),
 stroke([[W-16,14,decoZ0+2],[W-12,19,9],[W-7,29,decoZ1],[W-23,24,7]], [2.2,1.7,1.25,1],0.53)
);
// 左下
const bottomLeft = union(
 stroke([[8,D-8,decoZ0],[2,D-25,7.5],[13,D-38,decoZ1],[28,D-25,decoZ0+3]], [Rmain,3.0,2.2,Rtip],0.91),
 stroke([[13,D-7,decoZ0+1],[5,D-19,9],[13,D-29,decoZ1-0.6],[23,D-16,7.3]], [3.4,2.2,1.4,Rtip*0.98],0.7),
 stroke([[12,D-16,decoZ0+1.3],[10,D-24,7],[17,D-36,decoZ1-0.7],[30,D-18,decoZ0+3.4]], [2.0,2.0,1.15,1],0.59),
 stroke([[14,D-12,decoZ0+0.6],[1,D-13,8],[9,D-32,decoZ1-1],[23,D-24,7]], [2.1,1.5,1.19,1],0.5)
);
// 右下
const bottomRight = union(
 stroke([[W-8,D-8,decoZ0],[W-2,D-23,7.8],[W-12,D-37,decoZ1-0.3],[W-29,D-27,decoZ0+2.1]], [Rmain,3,2.2,Rtip],0.91),
 stroke([[W-14,D-14,decoZ0],[W-4,D-17,9.5],[W-18,D-27,decoZ1-0.8],[W-32,D-12,7]], [2.5,2.1,1.5,1],0.7),
 stroke([[W-19,D-10,decoZ0+1.6],[W-8,D-20,9],[W-18,D-37,decoZ1-0.7],[W-27,D-19,decoZ0+3.2]], [2.1,1.7,1.15,1],0.62),
 stroke([[W-10,D-13,decoZ0+1],[W-8,D-28,9],[W-25,D-33,decoZ1-0.5],[W-32,D-16,decoZ0+2.6]], [1.7,1.3,1.15,1],0.55)
);
return union(base,topLeft,topRight,bottomLeft,bottomRight);"}}]}
